  pMe = `%1$s (%2$s)`,
  mMe = `Analog`,
  hMe = `Trigger`,
  gMe = `Taste`,
  _Me = `Bedienelement hinzufügen`,
  vMe = `Bedienelement ändern`,
  yMe = `Befehl ändern`,
  bMe = `Bedienelement entfernen`,
  xMe = `Bedienelement bearbeiten`,
  SMe = `Einstellungen`,
  CMe = `Wählen Sie ein Bedienelement für %1$s`,
  wMe = `Wählen Sie einen Modus für %1$s`,
  TMe = `Lenkt einen virtuellen Stick mithilfe des Trackpads ab und nutzt dessen Position direkt, um den Grad der Auslenkung zu steuern.`,
  EMe = `Lenkt einen virtuellen Stick mithilfe des Gyroskops ab und nutzt dessen Position direkt, um den Grad der Auslenkung zu steuern.`,
  DMe = `Bewegt den Mauszeiger mit gleichbleibender Geschwindigkeit, solange Sie eine Auslenkung aufrechterhalten, und beschleunigt diesen bei erhöhtem Druck.`,
  OMe = `Bewegt den Mauszeiger basierend auf Ihren Bewegungen auf dem Trackpad (genauso wie bei einem Laptop).`,
  kMe = `Früherer Stick-Maus-Modus, der für Konfigurationen beibehalten wird, die diesen bereits verwenden.`,
  AMe = `Wandelt Bewegungen des Controllers in Mausbewegungen um, sodass Sie durch Neigung des Controllers zielen können.`,
  jMe = `Sendet Stick-Eingaben an die Kamera, wobei die Erhöhung des Drucks die Drehgeschwindigkeit der Kamera bestimmt.`,
  MMe = `Wandelt Bewegungen des Controllers in Stick-Eingaben zur Steuerung der Kamera um, für Spiele, die eher für einen Stick als eine Maus ausgelegt sind.`,
  NMe = `Wandelt Bewegungen des Controllers in Stick-Auslenkungen um, sodass eine erhöhte Neigung einem erhöhten Druck des Sticks gleichkommt.`,
  PMe = `Ordnet das Trackpad einem bestimmten Bereich des Bildschirms zu, sodass ein bestimmter Teil des Trackpads immer auf dieselbe Stelle zeigt.`,
  FMe = `Überträgt einen Kamerawinkel direkt ans Spiel (sofern vom Spiel unterstützt), anstatt, wie bei den anderen Modi, dafür die Bewegungen einer Maus oder eines Sticks zu verwenden.`,
  IMe = `Das Bedienelement sendet keine Befehle aus, solange diese Option ausgewählt ist.`,
  LMe = `Sendet Stick-Eingaben an das Spiel, interpretiert Bewegungen des Trackpads jedoch als Mauseingaben. Für Spiele, die für einen Stick zum Zielen oder Bewegen eines Zeigers ausgelegt sind.`,
